package ai.xzkj.recruitment.resumes;
import jakarta.validation.Valid;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController public class ResumeIntakeController{private final ResumeIntakeService service;private final ResumeAnalysisService analysis;public ResumeIntakeController(ResumeIntakeService s,ResumeAnalysisService a){service=s;analysis=a;}@GetMapping("/api/resume-intakes")public List<ResumeIntakeResponse> list(){return service.list();}@PostMapping("/api/candidate-contacts/{contactId}/resume-intakes")public ResumeIntakeResponse create(@PathVariable UUID contactId,@Valid@RequestBody ResumeIntakeCreateRequest r){return service.create(contactId,r);}@PutMapping("/api/resume-intakes/{id}/review")public ResumeIntakeResponse review(@PathVariable UUID id,@Valid@RequestBody ResumeIntakeReviewRequest r){return service.review(id,r);}@PostMapping("/api/resume-intakes/{id}/analysis")public ResumeAnalysisResponse analyze(@PathVariable UUID id,@Valid@RequestBody ResumeAnalysisRequest r){return analysis.analyze(id,r);}@PostMapping(value="/api/resume-intakes/{id}/document-preview",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResumeDocumentPreviewResponse previewDocument(@PathVariable UUID id,@RequestPart("file") MultipartFile file){return analysis.previewFile(id,file);}@GetMapping("/api/resume-intakes/{id}/analysis-runs")public List<ResumeAnalysisResponse> analysisRuns(@PathVariable UUID id){return analysis.list(id);}@PostMapping("/api/resume-analysis-runs/{id}/feedback")public ResumeAnalysisResponse feedback(@PathVariable UUID id,@Valid@RequestBody ResumeAnalysisFeedbackRequest r){return analysis.feedback(id,r);}}
